{"cmd":"python - <<'PY'
import csv, re, math, statistics
from collections import Counter

def parse_rating(s):
    s=(s or '').strip()
    if not s: return None
    m=re.search(r"\d+(?:\.\d+)?", s)
    return float(m.group(0)) if m else None

def parse_int(s):
    s=(s or '').strip()
    if not s: return None
    s=s.replace(',','')
    try: return int(float(s))
    except: return None

pos_words=set(['good','great','excellent','nice','best','awesome','perfect','value','fast','easy','love','quality','comfortable','sound','battery','fit','strong','durable','fine','satisfied'])
neg_words=set(['bad','poor','worst','waste','broken','damage','problem','issue','disappoint','not','return','low','hard','slow','cheap','defective'])

ct_pos=Counter(); ct_neg=Counter()

with open('benchmark/data.csv', newline='', encoding='utf-8') as f:
    r=csv.DictReader(f)
    for row in r:
        rt=parse_rating(row.get('rating'))
        text=((row.get('review_title') or '')+' '+(row.get('review_content') or '')).lower()
        words=re.findall(r"[a-z]{3,}", text)
        if rt is None: continue
        if rt>=4.0:
            for w in words:
                if w in pos_words:
                    ct_pos[w]+=1
        if rt<=3.0:
            for w in words:
                if w in neg_words:
                    ct_neg[w]+=1

print('top positive tokens', ct_pos.most_common(10))
print('top negative tokens', ct_neg.most_common(10))
PY"}

