    .table{width:100%; border-collapse:separate; border-spacing:0; overflow:hidden; border-radius:12px; border:1px solid rgba(255,255,255,0.08);}
    .table th,.table td{padding:10px 10px; font-size:12.5px; border-bottom:1px solid rgba(255,255,255,0.06);}
    .table th{color:var(--muted); font-weight:600; text-align:left; background:rgba(255,255,255,0.02); position:sticky; top:0;}
    .table tr:last-child td{border-bottom:none;}
    .num{text-align:right; font-variant-numeric: tabular-nums;}
    .badge{display:inline-block; padding:2px 8px; border-radius:999px; font-size:11px; border:1px solid rgba(255,255,255,0.14); color:var(--muted);} 

    .callout{display:flex; gap:10px; align-items:flex-start; padding:12px; border-radius:12px; border:1px solid rgba(255,255,255,0.10);
      background:rgba(99,179,255,0.08);
    }
    .callout strong{display:block; margin-bottom:3px;}
    .callout p{margin:0; color:var(--text); line-height:1.45;}

    .pill{padding:3px 10px; border-radius:999px; background:rgba(124,242,193,0.12); border:1px solid rgba(124,242,193,0.24); color:var(--accent2); font-size:11px;}
    .pill.warn{background:rgba(255,204,102,0.10); border-color:rgba(255,204,102,0.24); color:var(--warn);} 
    .pill.bad{background:rgba(255,107,107,0.10); border-color:rgba(255,107,107,0.22); color:var(--bad);} 

    .chart{width:100%; height:auto;}
    .foot{color:var(--muted); font-size:12px; margin-top:10px; line-height:1.4;}
    .hr{height:1px; background:rgba(255,255,255,0.08); margin:16px 0 0;}

    .reco li{margin:8px 0; line-height:1.45;}
    .reco b{color:var(--text);} 

    .small{font-size:12px; color:var(--muted);}

    a{color:var(--accent); text-decoration:none;}
    a:hover{text-decoration:underline;}

    /* print */
    @media print{
      html,body{background:#fff; color:#111;}
      .card{box-shadow:none;}
      .meta, .sub, .small, .foot{color:#333;}
    }
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div>
        <h1>Amazon Product Catalog Performance & Customer Sentiment Analysis</h1>
        <p class="sub">1,465 Amazon India products analyzed across pricing, discounts, customer ratings, engagement (rating counts), and lightweight review-theme signals. Built to guide assortment curation, pricing adjustments, and promo planning.</p>
      </div>
      <div class="meta">
        <div><span class="badge">Generated</span> <span id="genDate"></span></div>
        <div class="small">Source: <code>benchmark/data.csv</code></div>
      </div>
    </header>

    <!-- EXECUTIVE OVERVIEW -->
    <div class="section-title">
      <h2>Executive Overview</h2>
      <p>Headline KPIs and what they imply about catalog health and promotional efficiency.</p>
    </div>

    <div class="grid">
      <div class="card span-3"><div class="kpi"><div class="label">Products Analyzed</div><div class="value" id="kpiProducts"></div><div class="note" id="kpiMissing"></div></div></div>
      <div class="card span-3"><div class="kpi"><div class="label">Average Rating (1–5)</div><div class="value" id="kpiAvgRating"></div><div class="note">Catalog-level satisfaction signal.</div></div></div>
      <div class="card span-3"><div class="kpi"><div class="label">Median Discount %</div><div class="value" id="kpiMedianDiscount"></div><div class="note">Typical promo depth in the catalog.</div></div></div>
      <div class="card span-3"><div class="kpi"><div class="label">High-Rating Share (≥ 4.0)</div><div class="value" id="kpiHighShare"></div><div class="note">Share of products meeting a strong quality bar.</div></div></div>

      <div class="card span-6">
        <h2>Discount Efficiency (Correlation)</h2>
        <div class="callout">
          <div>
            <div class="pill" id="pillEff"></div>
          </div>
          <div>
            <strong>Do deeper discounts improve satisfaction?</strong>
            <p>
              Correlation between <b>discount %</b> and <b>rating</b>: <b id="corrDR"></b>.
              Correlation between <b>discount %</b> and <b>review volume</b> (log10 rating_count): <b id="corrDVol"></b>.
            </p>
            <p class="small" style="margin-top:6px;">Interpretation: correlation captures direction/strength, not causation.</p>
          </div>
        </div>
        <div class="foot">Management takeaway: in this dataset, higher discounts do <b>not</b> align with higher ratings; discounting appears more likely to be tactical rather than a consistent driver of satisfaction.</div>
      </div>

      <div class="card span-6">
        <h2>Top-Level Categories (Avg Rating)</h2>
        <div id="catBar" class="chart"></div>
        <div class="foot">Only categories with ≥ 20 products are included for stability.</div>
      </div>

    </div>

    <!-- CATEGORY PERFORMANCE -->
    <div class="section-title">
      <h2>Category Performance Breakdown</h2>
      <p>Where customer satisfaction and engagement concentrate, and which categories need attention.</p>
    </div>

    <div class="grid">
      <div class="card span-6">
        <h2>Best / Worst Categories (Avg Rating)</h2>
        <div id="catRanking" class="chart"></div>
        <div class="foot">Ranking uses top-level category average rating (min 20 products).</div>
      </div>
      <div class="card span-6">
        <h2>Category Engagement (Mean Rating Count)</h2>
        <div id="catEng" class="chart"></div>
        <div class="foot">Engagement measured by mean <code>rating_count</code> (min 20 products).</div>
      </div>

      <div class="card span-12">
        <h2>Top-Level Category Table</h2>
        <div style="max-height: 360px; overflow:auto; border-radius:12px;">
          <table class="table" id="catTable"></table>
        </div>
        <div class="foot">Columns: product count, average rating, median/mean rating count, and average discount %.</div>
      </div>

      <div class="card span-12">
        <h2>Sub-Category Highlights (Min 30 products)</h2>
        <div class="grid" style="margin-top:10px;">
          <div class="span-6">
            <div class="small" style="margin:0 0 8px;">Top sub-categories by avg rating</div>
            <div style="max-height: 260px; overflow:auto; border-radius:12px;">
              <table class="table" id="subTop"></table>
            </div>
          </div>
          <div class="span-6">
            <div class="small" style="margin:0 0 8px;">Most engaged sub-categories by median rating_count</div>
            <div style="max-height: 260px; overflow:auto; border-radius:12px;">
              <table class="table" id="subEng"></table>
            </div>
          </div>
        </div>
        <div class="foot">Sub-category = 2nd level in <code>category</code> path.</div>
      </div>
    </div>

    <!-- PRICING & DISCOUNT -->
    <div class="section-title">
      <h2>Pricing & Discount Strategy Analysis</h2>
      <p>Quantifies whether discount depth correlates with higher ratings or simply more reviews, and shows how ratings vary across discount buckets.</p>
    </div>

    <div class="grid">
      <div class="card span-8">
        <h2>Discount % vs Rating (Scatter)</h2>
        <div id="scatterDR" class="chart"></div>
        <div class="foot">Each point is a product (n shown in chart). The trendline is a simple linear fit for directional reading.</div>
      </div>
      <div class="card span-4">
        <h2>Discount Buckets</h2>
        <div id="discBuckets" class="chart"></div>
        <div class="foot">Average rating and median engagement by discount bucket.</div>
      </div>

      <div class="card span-12">
        <h2>Discount % vs Review Volume (Scatter, log scale)</h2>
        <div id="scatterDVol" class="chart"></div>
        <div class="foot">Y-axis is <code>log10(rating_count + 1)</code> to keep extreme products from dominating the view.</div>
      </div>

      <div class="card span-12">
        <h2>Price vs Rating (Context)</h2>
        <div class="callout" style="background:rgba(124,242,193,0.08); border-color:rgba(124,242,193,0.18);">
          <div><span class="pill" style="background:rgba(124,242,193,0.18); border-color:rgba(124,242,193,0.30);">Context</span></div>
          <div>
            <strong>Price level has a weak positive relationship with rating.</strong>
            <p>Correlation between discounted price and rating: <b id="corrPriceRating"></b>. This suggests higher-priced items are <i>slightly</i> higher rated on average, but the relationship is modest.</p>
          </div>
        </div>
      </div>
    </div>

    <!-- CUSTOMER ENGAGEMENT -->
    <div class="section-title">
      <h2>Customer Engagement & Rating Distribution</h2>
      <p>Shows how ratings and rating counts distribute across the catalog and identifies extreme engagement products.</p>
    </div>

    <div class="grid">
      <div class="card span-6">
        <h2>Rating Distribution</h2>
        <div id="ratingHist" class="chart"></div>
        <div class="foot">Histogram in 0.1 rating increments.</div>
      </div>
      <div class="card span-6">
        <h2>Rating Count Distribution (log10 bins)</h2>
        <div id="rcHist" class="chart"></div>
        <div class="foot">Counts by order of magnitude (log10 bin).</div>
      </div>

      <div class="card span-12">
        <h2>Most Engaged Products (Top by rating_count)</h2>
        <div style="max-height: 320px; overflow:auto; border-radius:12px;">
          <table class="table" id="topProducts"></table>
        </div>
        <div class="foot">Use this list to sanity-check: are these “hero” SKUs you want to protect/feature?</div>
      </div>
    </div>

    <!-- REVIEW SENTIMENT -->
    <div class="section-title">
      <h2>Review Sentiment Snapshot</h2>
      <p>Lightweight theme scan from review titles/content (product-level, comma-separated multi-review fields). This is not a full NLP sentiment model; it surfaces frequently occurring positive/negative keywords.</p>
    </div>

    <div class="grid">
      <div class="card span-6">
        <h2>Common Positive Themes (Higher-rated products)</h2>
        <div id="posThemes" class="chart"></div>
        <div class="foot">Counts from products with rating ≥ 4.0.</div>
      </div>
      <div class="card span-6">
        <h2>Common Negative Themes (Lower-rated products)</h2>
        <div id="negThemes" class="chart"></div>
        <div class="foot">Counts from products with rating ≤ 3.0 (smaller set, hence lower counts).</div>
      </div>
      <div class="card span-12">
        <h2>What to do with these themes</h2>
        <ul class="reco">
          <li><b>Use “quality”, “value”, “easy”, “battery”, “sound”</b> as review-driven merchandising angles for relevant categories where they naturally apply.</li>
          <li><b>Investigate “defective/broken/return” flags</b> in lower-rated products as potential quality-control and listing-accuracy issues.</li>
          <li><b>Promotional messaging</b> should avoid leaning purely on discount depth; emphasize product experience drivers instead.</li>
        </ul>
        <div class="foot">Note: Since reviews are stored as comma-separated strings per product row, counts here reflect token presence in those strings rather than per-review counts.</div>
      </div>
    </div>

    <!-- RECOMMENDATIONS -->
    <div class="section-title">
      <h2>Strategic Recommendations</h2>
      <p>Actions explicitly tied to measured outcomes in this dataset.</p>
    </div>

    <div class="grid">
      <div class="card span-12">
        <ol class="reco" id="recoList"></ol>
        <div class="hr"></div>
        <div class="foot">
          Method notes: prices parsed from INR strings; discounts parsed from percent strings; <code>rating</code> parsed from first numeric token when malformed; engagement uses <code>rating_count</code>. All metrics and charts are computed directly from <code>benchmark/data.csv</code>.
        </div>
      </div>
    </div>

  </div>

  <script>
    // Embedded analysis (computed from data.csv) for a self-contained report
    const DATA = __DATA_JSON__;

    const fmtInt = (n) => (n==null ? '—' : n.toLocaleString('en-US'));
    const fmt1 = (n) => (n==null || !isFinite(n)) ? '—' : n.toFixed(1);
    const fmt2 = (n) => (n==null || !isFinite(n)) ? '—' : n.toFixed(2);
    const fmtPct = (n) => (n==null || !isFinite(n)) ? '—' : `${n.toFixed(1)}%`;

    const clamp = (v,a,b)=>Math.max(a,Math.min(b,v));

    function el(id){ return document.getElementById(id); }

    function pearsonFromPairs(pairs){
      const n=pairs.length;
      if(n<2) return null;
      let sx=0, sy=0;
      for(const p of pairs){ sx+=p.x; sy+=p.y; }
      const mx=sx/n, my=sy/n;
      let vx=0, vy=0, cov=0;
      for(const p of pairs){
        const dx=p.x-mx, dy=p.y-my;
        vx += dx*dx; vy += dy*dy; cov += dx*dy;
      }
      if(vx===0 || vy===0) return null;
      return cov / Math.sqrt(vx*vy);
    }

    function linearFit(pairs){
      // y = a + b x
      const n=pairs.length;
      if(n<2) return null;
      let sx=0, sy=0;
      for(const p of pairs){ sx+=p.x; sy+=p.y; }
      const mx=sx/n, my=sy/n;
      let sxx=0, sxy=0;
      for(const p of pairs){
        const dx=p.x-mx;
        sxx += dx*dx;
        sxy += dx*(p.y-my);
      }
      if(sxx===0) return {a:my, b:0};
      const b=sxy/sxx;
      const a=my - b*mx;
      return {a,b};
    }

    function svgWrap(inner, height=320){
      return `<svg viewBox="0 0 900 ${height}" width="100%" height="${height}" xmlns="http://www.w3.org/2000/svg" role="img">${inner}</svg>`;
    }

    function axes({x0=70,y0=270,w=800,h=220,xLabel='',yLabel=''}){
      const x1=x0+w, y1=y0-h;
      return `
        <g>
          <line x1="${x0}" y1="${y0}" x2="${x1}" y2="${y0}" stroke="rgba(255,255,255,0.35)"/>
          <line x1="${x0}" y1="${y0}" x2="${x0}" y2="${y1}" stroke="rgba(255,255,255,0.35)"/>
          <text x="${x0+w/2}" y="${y0+42}" fill="rgba(255,255,255,0.70)" font-size="14" text-anchor="middle">${xLabel}</text>
          <text x="${x0-48}" y="${y1+h/2}" fill="rgba(255,255,255,0.70)" font-size="14" text-anchor="middle" transform="rotate(-90 ${x0-48} ${y1+h/2})">${yLabel}</text>
        </g>
      `;
    }

    function barChartHorizontal({rows, valueKey, labelKey, title='', xMin=null, xMax=null, xLabel='', valueFmt=(v)=>String(v), height=320, color="var(--accent)"}){
      // rows sorted desc recommended
      const padL=280, padR=40, padT=24, padB=44;
      const h=height;
      const chartH = h - padT - padB;
      const barGap=10;
      const barH = (chartH - barGap*(rows.length-1)) / rows.length;
      const values = rows.map(r=>r[valueKey]).filter(v=>v!=null && isFinite(v));
      const minV = (xMin!=null)?xMin:Math.min(...values);
      const maxV = (xMax!=null)?xMax:Math.max(...values);
      const x0=padL, y0=h-padB;
      const w=900-padL-padR;

      const scaleX=(v)=> x0 + ( (v-minV) / (maxV-minV || 1) )*w;

      let grid='';
      const ticks=5;
      for(let i=0;i<=ticks;i++){
        const t=minV + (maxV-minV)*i/ticks;
        const x=scaleX(t);
        grid += `<line x1="${x}" y1="${y0}" x2="${x}" y2="${padT}" stroke="rgba(255,255,255,0.08)" />`;
        grid += `<text x="${x}" y="${y0+18}" fill="rgba(255,255,255,0.60)" font-size="12" text-anchor="middle">${valueFmt(t)}</text>`;
      }

      let bars='';
      rows.forEach((r,idx)=>{
        const y = padT + idx*(barH+barGap);
        const v = r[valueKey];
        const x1 = scaleX(v);
        const xStart = scaleX(minV);
        const bw = Math.max(0, x1-xStart);
        const label = r[labelKey];
        bars += `
          <text x="${padL-10}" y="${y + barH*0.68}" fill="rgba(255,255,255,0.85)" font-size="13" text-anchor="end">${escapeXml(label)}</text>
          <rect x="${xStart}" y="${y}" width="${bw}" height="${barH}" rx="8" fill="${color}" opacity="0.85"/>
          <text x="${x1+6}" y="${y + barH*0.68}" fill="rgba(255,255,255,0.85)" font-size="13" text-anchor="start">${valueFmt(v)}</text>
        `;
      });

      const inner = `
        <rect x="0" y="0" width="900" height="${h}" fill="transparent"/>
        <text x="20" y="22" fill="rgba(255,255,255,0.92)" font-size="15" font-weight="600">${escapeXml(title)}</text>
        ${grid}
        ${bars}
        <text x="${padL + w/2}" y="${h-8}" fill="rgba(255,255,255,0.65)" font-size="13" text-anchor="middle">${escapeXml(xLabel)}</text>
      `;
      return svgWrap(inner, h);
    }

    function scatterPlot({pairs, xLabel, yLabel, yTransform=null, yTicks=null, height=360, title='', yFmt=(v)=>v.toFixed(2), xFmt=(v)=>v.toFixed(0), drawTrend=true}){
      const padL=70, padR=28, padT=30, padB=58;
      const h=height;
      const x0=padL, y0=h-padB;
      const w=900-padL-padR;
      const ch=h-padT-padB;

      const xs=pairs.map(p=>p.x).filter(v=>v!=null && isFinite(v));
      const ys=pairs.map(p=>p.y).filter(v=>v!=null && isFinite(v));
      const xmin=Math.min(...xs), xmax=Math.max(...xs);
      const ymin=Math.min(...ys), ymax=Math.max(...ys);

      const sx=(v)=> x0 + ((v-xmin)/(xmax-xmin || 1))*w;
      const sy=(v)=> y0 - ((v-ymin)/(ymax-ymin || 1))*ch;

      let grid='';
      const xt=5;
      for(let i=0;i<=xt;i++){
        const t=xmin + (xmax-xmin)*i/xt;
        const x=sx(t);
        grid += `<line x1="${x}" y1="${y0}" x2="${x}" y2="${padT}" stroke="rgba(255,255,255,0.08)" />`;
        grid += `<text x="${x}" y="${y0+18}" fill="rgba(255,255,255,0.60)" font-size="12" text-anchor="middle">${xFmt(t)}</text>`;
      }
      const yt= (yTicks!=null)?yTicks:5;
      for(let i=0;i<=yt;i++){
        const t=ymin + (ymax-ymin)*i/yt;
        const y=sy(t);
        grid += `<line x1="${x0}" y1="${y}" x2="${x0+w}" y2="${y}" stroke="rgba(255,255,255,0.08)" />`;
        grid += `<text x="${x0-8}" y="${y+4}" fill="rgba(255,255,255,0.60)" font-size="12" text-anchor="end">${yFmt(t)}</text>`;
      }

      // decimate points if huge for SVG perf
      const maxPoints=3500;
      const step = Math.max(1, Math.floor(pairs.length / maxPoints));

      let dots='';
      for(let i=0;i<pairs.length;i+=step){
        const p=pairs[i];
        const cx=sx(p.x);
        const cy=sy(p.y);
        dots += `<circle cx="${cx}" cy="${cy}" r="2" fill="rgba(99,179,255,0.55)"/>`;
      }

      let trend='';
      if(drawTrend){
        const fit=linearFit(pairs);
        if(fit){
          const yA=fit.a + fit.b*xmin;
          const yB=fit.a + fit.b*xmax;
          trend = `<line x1="${sx(xmin)}" y1="${sy(yA)}" x2="${sx(xmax)}" y2="${sy(yB)}" stroke="rgba(124,242,193,0.85)" stroke-width="2"/>`;
        }
      }

      const inner = `
        <rect x="0" y="0" width="900" height="${h}" fill="transparent"/>
        <text x="20" y="22" fill="rgba(255,255,255,0.92)" font-size="15" font-weight="600">${escapeXml(title)} <tspan fill="rgba(255,255,255,0.65)" font-weight="500">(n=${pairs.length})</tspan></text>
        ${grid}
        ${dots}
        ${trend}
        ${axes({x0,y0,w,h:ch,xLabel,yLabel})}
      `;
      return svgWrap(inner, h);
    }

    function columnChart({rows, xKey, yKey, title='', xLabel='', yLabel='', yFmt=(v)=>String(v), height=320, color='var(--accent)'}){
      const padL=70, padR=28, padT=30, padB=60;
      const h=height;
      const x0=padL, y0=h-padB;
      const w=900-padL-padR;
      const ch=h-padT-padB;

      const ys=rows.map(r=>r[yKey]).filter(v=>v!=null && isFinite(v));
      const ymin=0;
      const ymax=Math.max(...ys);

      const barW = w / rows.length;

      let grid='';
      const yt=5;
      for(let i=0;i<=yt;i++){
        const t=ymin + (ymax-ymin)*i/yt;
        const y=y0 - (t/(ymax||1))*ch;
        grid += `<line x1="${x0}" y1="${y}" x2="${x0+w}" y2="${y}" stroke="rgba(255,255,255,0.08)" />`;
        grid += `<text x="${x0-8}" y="${y+4}" fill="rgba(255,255,255,0.60)" font-size="12" text-anchor="end">${yFmt(t)}</text>`;
      }

      let bars='';
      rows.forEach((r,idx)=>{
        const v=r[yKey];
        const x=x0 + idx*barW + barW*0.15;
        const bw=barW*0.7;
        const bh=(v/(ymax||1))*ch;
        const y=y0-bh;
        const label=r[xKey];
        bars += `<rect x="${x}" y="${y}" width="${bw}" height="${bh}" rx="6" fill="${color}" opacity="0.85"/>`;
        // x labels (sparse if many)
        if(rows.length<=16 || idx%Math.ceil(rows.length/16)===0){
          bars += `<text x="${x+bw/2}" y="${y0+18}" fill="rgba(255,255,255,0.60)" font-size="12" text-anchor="middle">${escapeXml(String(label))}</text>`;
        }
      });

      const inner = `
        <rect x="0" y="0" width="900" height="${h}" fill="transparent"/>
        <text x="20" y="22" fill="rgba(255,255,255,0.92)" font-size="15" font-weight="600">${escapeXml(title)}</text>
        ${grid}
        ${bars}
        ${axes({x0,y0,w,h:ch,xLabel,yLabel})}
      `;
      return svgWrap(inner, h);
    }

    function escapeXml(str){
      return String(str)
        .replaceAll('&','&amp;')
        .replaceAll('<','&lt;')
        .replaceAll('>','&gt;')
        .replaceAll('"','&quot;')
        .replaceAll("'",'&#39;');
    }

    function renderTable(elm, columns, rows, maxRows=null){
      const head = `<tr>${columns.map(c=>`<th>${escapeXml(c.label)}</th>`).join('')}</tr>`;
      const bodyRows = (maxRows==null? rows : rows.slice(0,maxRows)).map(r=>{
        return `<tr>${columns.map(c=>{
          const v = (typeof c.value==='function') ? c.value(r) : r[c.value];
          const cls = c.className || '';
          return `<td class="${cls}">${v==null?'—':escapeXml(String(v))}</td>`;
        }).join('')}</tr>`;
      }).join('');
      elm.innerHTML = `<thead>${head}</thead><tbody>${bodyRows}</tbody>`;
    }

    function correlationPill(r){
      const a=Math.abs(r);
      if(a<0.10) return {text:'Near-zero relationship', cls:''};
      if(a<0.30) return {text:'Weak relationship', cls:'warn'};
      if(a<0.50) return {text:'Moderate relationship', cls:'warn'};
      return {text:'Strong relationship', cls:'bad'};
    }

    // Fill KPIs
    (function(){
      el('genDate').textContent = new Date().toLocaleString('en-US', {year:'numeric', month:'short', day:'2-digit'});
      const k=DATA.kpis;
      el('kpiProducts').textContent = fmtInt(k.products_total);
      el('kpiMissing').textContent = `Missing values: rating=${fmtInt(k.missing_rating)}, rating_count=${fmtInt(k.missing_rating_count)}.`;
      el('kpiAvgRating').textContent = fmt2(k.avg_rating);
      el('kpiMedianDiscount').textContent = fmtPct(k.median_discount_pct);
      el('kpiHighShare').textContent = `${(k.high_rating_share*100).toFixed(1)}%`;
      el('corrDR').textContent = fmt3(k.corr_discount_pct_rating);
      el('corrDVol').textContent = fmt3(k.corr_discount_pct_log_rating_count);
      el('corrPriceRating').textContent = fmt3(k.corr_discounted_price_rating);

      const pill=correlationPill(k.corr_discount_pct_rating);
      const p=el('pillEff');
      p.textContent = pill.text;
      if(pill.cls) p.classList.add(pill.cls);
    })();

    function fmt3(n){ return (n==null || !isFinite(n)) ? '—' : n.toFixed(3); }

    // Category bar (avg rating)
    (function(){
      const rows = DATA.category_by_rating.slice(0,6).map(r=>({
        category: r.category,
        avg_rating: r.avg_rating
      }));
      el('catBar').innerHTML = barChartHorizontal({
        rows,
        valueKey:'avg_rating',
        labelKey:'category',
        title:'Top categories by average rating',
        xMin:3.6,
        xMax:4.6,
        xLabel:'Average rating (1–5)',
        valueFmt:(v)=>v.toFixed(2)
      });
    })();

    // Best / worst ranking
    (function(){
      const best = DATA.category_by_rating.slice(0,4).map(r=>({label:r.category, value:r.avg_rating}));
      const worst = [...DATA.category_by_rating].slice(-4).map(r=>({label:r.category, value:r.avg_rating}));
      const rows = [...best, ...worst].map(r=>({category:r.label, avg_rating:r.value}));
      el('catRanking').innerHTML = barChartHorizontal({
        rows,
        valueKey:'avg_rating',
        labelKey:'category',
        title:'Best vs worst (avg rating)',
        xMin:3.6,
        xMax:4.6,
        xLabel:'Average rating',
        valueFmt:(v)=>v.toFixed(2),
        color:'var(--accent2)'
      });
    })();

    // Engagement chart
    (function(){
      const rows = DATA.category_by_engagement.slice(0,6).map(r=>({category:r.category, mean_rating_count:r.mean_rating_count}));
      el('catEng').innerHTML = barChartHorizontal({
        rows,
        valueKey:'mean_rating_count',
        labelKey:'category',
        title:'Top categories by mean rating_count',
        xMin:0,
        xLabel:'Mean rating_count',
        valueFmt:(v)=>Math.round(v).toLocaleString('en-US'),
        height:320,
        color:'var(--accent)'
      });
    })();

    // Category table
    (function(){
      const rows = [...DATA.category_by_rating].sort((a,b)=>b.product_count-a.product_count);
      renderTable(el('catTable'), [
        {label:'Category', value:'category'},
        {label:'Products', value:(r)=>fmtInt(r.product_count), className:'num'},
        {label:'Avg rating', value:(r)=>fmt2(r.avg_rating), className:'num'},
        {label:'Median rating_count', value:(r)=>fmtInt(r.median_rating_count), className:'num'},
        {label:'Mean rating_count', value:(r)=>fmtInt(Math.round(r.mean_rating_count)), className:'num'},
        {label:'Avg discount %', value:(r)=>fmtPct(r.avg_discount_pct), className:'num'},
      ], rows);
    })();

    // Subcategory tables
    (function(){
      const top = DATA.subcat_by_rating.slice(0,12);
      const eng = DATA.subcat_by_engagement.slice(0,12);
      renderTable(el('subTop'), [
        {label:'Top', value:'top'},
        {label:'Sub', value:'sub'},
        {label:'Products', value:(r)=>fmtInt(r.product_count), className:'num'},
        {label:'Avg rating', value:(r)=>fmt2(r.avg_rating), className:'num'},
        {label:'Median rating_count', value:(r)=>fmtInt(r.median_rating_count), className:'num'},
      ], top);
      renderTable(el('subEng'), [
        {label:'Top', value:'top'},
        {label:'Sub', value:'sub'},
        {label:'Products', value:(r)=>fmtInt(r.product_count), className:'num'},
        {label:'Median rating_count', value:(r)=>fmtInt(r.median_rating_count), className:'num'},
        {label:'Avg rating', value:(r)=>fmt2(r.avg_rating), className:'num'},
      ], eng);
    })();

    // Scatter: discount vs rating
    (function(){
      const pairs = DATA.scatter_discount_rating;
      el('scatterDR').innerHTML = scatterPlot({
        pairs,
        xLabel:'Discount %',
        yLabel:'Rating',
        title:'Discount depth vs customer rating',
        yFmt:(v)=>v.toFixed(2),
        xFmt:(v)=>v.toFixed(0)
      });
    })();

    // Discount buckets chart (avg rating)
    (function(){
      const rows = DATA.discount_buckets.map(r=>({bucket:r.bucket, avg_rating:r.avg_rating}));
      el('discBuckets').innerHTML = columnChart({
        rows,
        xKey:'bucket',
        yKey:'avg_rating',
        title:'Avg rating by discount bucket',
        xLabel:'Discount bucket',
        yLabel:'Average rating',
        yFmt:(v)=>v.toFixed(2),
        height:300,
        color:'var(--warn)'
      });
    })();

    // Scatter: discount vs rating_count (log10)
    (function(){
      const raw = DATA.scatter_discount_rating_count;
      const pairs = raw.map(p=>({x:p.x, y:Math.log10(p.y+1)}));
      el('scatterDVol').innerHTML = scatterPlot({
        pairs,
        xLabel:'Discount %',
        yLabel:'log10(rating_count + 1)',
        title:'Discount depth vs review volume (log-scaled)',
        yFmt:(v)=>v.toFixed(2),
        xFmt:(v)=>v.toFixed(0)
      });
    })();

    // Rating histogram
    (function(){
      const rows = DATA.rating_hist.map(r=>({x:r.rating, y:r.count}));
      // render as column chart with many bins
      const padL=70, padR=28, padT=30, padB=58;
      const h=320;
      const x0=padL, y0=h-padB;
      const w=900-padL-padR;
      const ch=h-padT-padB;

      const ymax=Math.max(...rows.map(r=>r.y));
      const xmin=Math.min(...rows.map(r=>r.x));
      const xmax=Math.max(...rows.map(r=>r.x));

      const sx=(v)=> x0 + ((v-xmin)/(xmax-xmin || 1))*w;
      const barW = w/rows.length;

      let grid='';
      for(let i=0;i<=5;i++){
        const t=(ymax)*i/5;
        const y=y0 - (t/(ymax||1))*ch;
        grid += `<line x1="${x0}" y1="${y}" x2="${x0+w}" y2="${y}" stroke="rgba(255,255,255,0.08)" />`;
        grid += `<text x="${x0-8}" y="${y+4}" fill="rgba(255,255,255,0.60)" font-size="12" text-anchor="end">${Math.round(t).toLocaleString('en-US')}</text>`;
      }

      let bars='';
      rows.forEach((r,idx)=>{
        const x=x0 + idx*barW;
        const bh=(r.y/(ymax||1))*ch;
        const y=y0-bh;
        bars += `<rect x="${x}" y="${y}" width="${Math.max(1,barW*0.92)}" height="${bh}" fill="rgba(99,179,255,0.75)"/>`;
        if(idx%Math.ceil(rows.length/10)===0){
          bars += `<text x="${x}" y="${y0+18}" fill="rgba(255,255,255,0.60)" font-size="12" text-anchor="start">${r.x.toFixed(1)}</text>`;
        }
      });

      const inner = `
        <rect x="0" y="0" width="900" height="${h}" fill="transparent"/>
        <text x="20" y="22" fill="rgba(255,255,255,0.92)" font-size="15" font-weight="600">Rating distribution</text>
        ${grid}
        ${bars}
        ${axes({x0,y0,w,h:ch,xLabel:'Rating (binned)',yLabel:'Products'})}
      `;
      el('ratingHist').innerHTML = svgWrap(inner, h);
    })();

    // Rating count log histogram
    (function(){
      const rows = DATA.rating_count_log_hist.map(r=>({bin:r.log10_bin, count:r.count}));
      // bins are integers: 0..6 etc
      const ymax=Math.max(...rows.map(r=>r.count));
      const chartRows = rows.map(r=>({bucket:`10^${r.bin}`, value:r.count}));
      el('rcHist').innerHTML = columnChart({
        rows: chartRows,
        xKey:'bucket',
        yKey:'value',
        title:'Rating_count distribution by magnitude',
        xLabel:'Order of magnitude (log10)',
        yLabel:'Products',
        yFmt:(v)=>Math.round(v).toLocaleString('en-US'),
        height:320,
        color:'rgba(124,242,193,0.85)'
      });
    })();

    // Top products table
    (function(){
      renderTable(el('topProducts'), [
        {label:'Product', value:(r)=>r.product_name},
        {label:'Category', value:(r)=>r.category_top},
        {label:'Rating', value:(r)=> (r.rating==null?'—':r.rating.toFixed(1)), className:'num'},
        {label:'Rating count', value:(r)=>fmtInt(r.rating_count), className:'num'},
        {label:'Discount %', value:(r)=>fmtPct(r.discount_pct), className:'num'},
        {label:'Discounted price (₹)', value:(r)=> (r.discounted_price==null?'—':Math.round(r.discounted_price).toLocaleString('en-US')), className:'num'},
        {label:'Actual price (₹)', value:(r)=> (r.actual_price==null?'—':Math.round(r.actual_price).toLocaleString('en-US')), className:'num'},
      ], DATA.top_products_by_rating_count);
    })();

    // Theme charts
    (function(){
      const pos = DATA.sentiment.positive_top.map(([w,c])=>({word:w, count:c}));
      const neg = DATA.sentiment.negative_top.map(([w,c])=>({word:w, count:c}));

      el('posThemes').innerHTML = barChartHorizontal({
        rows: pos,
        valueKey:'count',
        labelKey:'word',
        title:'Positive keyword frequency',
        xMin:0,
        xLabel:'Count',
        valueFmt:(v)=>Math.round(v).toLocaleString('en-US'),
        height:320,
        color:'rgba(124,242,193,0.85)'
      });

      el('negThemes').innerHTML = barChartHorizontal({
        rows: neg,
        valueKey:'count',
        labelKey:'word',
        title:'Negative keyword frequency',
        xMin:0,
        xLabel:'Count',
        valueFmt:(v)=>Math.round(v).toLocaleString('en-US'),
        height:320,
        color:'rgba(255,107,107,0.85)'
      });
    })();

    // Recommendations (data-backed)
    (function(){
      const k=DATA.kpis;
      const avgDisc=k.avg_discount_pct;
      const medDisc=k.median_discount_pct;
      const avgRating=k.avg_rating;
      const highShare=k.high_rating_share*100;
      const corrDR=k.corr_discount_pct_rating;
      const corrDVol=k.corr_discount_pct_log_rating_count;

      const bestCats=DATA.category_by_rating.slice(0,2);
      const worstCats=[...DATA.category_by_rating].slice(-2);
      const topEng=DATA.category_by_engagement.slice(0,2);

      const recos=[
        {
          title:'Avoid assuming deeper discounts improve satisfaction',
          text:`Discount % vs rating correlation is ${fmt3(corrDR)} (negative/weak). With an average discount of ${avgDisc.toFixed(1)}% (median ${medDisc.toFixed(1)}%), discounting should be used selectively—prioritize quality improvements and listing accuracy where ratings are lagging.`
        },
        {
          title:'Treat high-discount SKUs as margin-risk without commensurate rating lift',
          text:`Products in the 80%+ discount bucket average ${DATA.discount_buckets.find(d=>d.bucket==='80%+')?.avg_rating.toFixed(2) ?? '—'} rating, below lower-discount buckets (e.g., 0–20% bucket at ${DATA.discount_buckets.find(d=>d.bucket==='0–20%')?.avg_rating.toFixed(2) ?? '—'}). Use deep discounts primarily for clearance/traffic, not for “satisfaction improvement” goals.`
        },
        {
          title:'Double down on categories combining satisfaction and scale',
          text:`Among stable categories (≥20 products), top average ratings include ${bestCats.map(c=>`${c.category} (${c.avg_rating.toFixed(2)})`).join(', ')}. These are strong candidates for assortment expansion and visibility boosts, especially if supply and margin allow.`
        },
        {
          title:'Prioritize engagement-heavy categories for review-driven optimization',
          text:`Engagement is concentrated in ${topEng.map(c=>`${c.category} (mean rating_count ${Math.round(c.mean_rating_count).toLocaleString('en-US')})`).join(', ')}. Use these categories for faster learning loops: A/B test pricing, refresh images/titles, and monitor rating_count velocity.`
        },
        {
          title:'Target quality-control and expectation-setting for weaker categories',
          text:`Lower average ratings (≥20 products) include ${worstCats.map(c=>`${c.category} (${c.avg_rating.toFixed(2)})`).join(', ')}. Use review theme flags (e.g., “defective”, “broken”, “return”) to identify SKUs needing supplier remediation, better QA, or clearer specs.`
        },
      ];

      const list=el('recoList');
      list.innerHTML = recos.map(r=>`<li><b>${escapeXml(r.title)}:</b> ${escapeXml(r.text)}</li>`).join('');
    })();

  </script>
</body>
